-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 1
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 1 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 01', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 01 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-01.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga se a anotação é dado ou informação e justifique em uma frase.', 0.2, 'A anotação é **dado**: são fatos registrados **sem contexto** (não se sabe o que significa 17 nem a data).', 'Palavras-chave: dado; sem contexto/sem sentido. Nota cheia (0,2): diz "dado" e justifica pela falta de contexto. Metade (0,1): diz "dado" sem justificar. Zero (0): diz que já é informação.'),
      (v_atividade, 1, 2, 'Reescreva a anotação como informação, dando contexto aos dados.', 0.4, 'Exemplo: "A aluna **Ana**, de **17 anos**, matriculou-se no curso de **Programação** em **09/10/2026**." Os dados foram **organizados e ganharam sentido**.', 'Palavras-chave: frase com os quatro dados interpretados (nome, idade, data, curso). Nota cheia (0,4): reescreve com contexto usando os dados corretamente. Metade (0,2): reescreve com contexto, mas deixa de fora ou interpreta errado um dos dados. Zero (0): repete a anotação sem contexto.'),
      (v_atividade, 1, 3, 'Explique o que seria o banco de dados da escola e cite três "coisas" que ele precisa guardar.', 0.4, 'O banco de dados da escola é o **conjunto organizado de dados relacionados**, guardado de forma **permanente**, que pode ser **consultado e atualizado** pelo sistema. Deve guardar, por exemplo: **alunos, cursos, matrículas** (também turmas, professores, pagamentos, notas).', 'Palavras-chave: conjunto organizado; dados relacionados; permanente; consultar/atualizar; três entidades coerentes. Nota cheia (0,4): definição correta + três itens coerentes. Metade (0,2): só a definição ou só os três itens. Zero (0): confunde banco de dados com o programa, o site ou o computador e não cita itens coerentes.'),
      (v_atividade, 2, 1, 'Explique, em uma frase, o que é um SGBD.', 0.2, 'O **SGBD** (Sistema Gerenciador de Banco de Dados) é o **programa que cria, guarda e gerencia** o banco de dados, executando os pedidos do sistema.', 'Palavras-chave: programa/software; gerencia/guarda o banco. Nota cheia (0,2): definição com programa + gerenciar. Metade (0,1): "é onde ficam os dados" sem dizer que é o programa gerenciador. Zero (0): confunde com planilha, site ou linguagem.'),
      (v_atividade, 2, 2, 'Explique como o sistema web deve chegar aos dados quando existe um SGBD.', 0.4, 'O sistema web **não abre o arquivo do banco direto**: o back-end **envia um pedido (em SQL) ao SGBD**, que **executa** e **devolve o resultado**.', 'Palavras-chave: pede ao SGBD; SQL; executa; devolve resultado; não acessa o arquivo direto. Nota cheia (0,4): descreve o pedido ao SGBD e o retorno. Metade (0,2): diz só "usa o SGBD" sem explicar o pedido/retorno. Zero (0): diz que o sistema grava direto no arquivo.'),
      (v_atividade, 2, 3, 'Cite dois problemas que a loja teria gravando os pedidos num arquivo de texto e justifique cada um.', 0.4, 'Dois entre: **concorrência** (dois pedidos ao mesmo tempo podem se sobrescrever); **integridade** (nada impede dados errados, como preço negativo); **controle de acesso** (qualquer um que abre o arquivo vê tudo); **consulta lenta** com muitos pedidos; **recuperação** (sem backup/restauração se o arquivo corromper).', 'Palavras-chave: dois problemas entre concorrência, integridade, acesso, desempenho, recuperação, cada um com justificativa. Nota cheia (0,4): dois problemas justificados. Metade (0,2): um problema justificado ou dois sem justificativa. Zero (0): problemas sem relação com dados ("o site fica feio").'),
      (v_atividade, 3, 1, 'Nomeie a funcionalidade do SGBD de cada uma das três situações.', 0.2, '(1) **Concorrência**; (2) **Controle de acesso**; (3) **Recuperação** (backup e restauração).', 'Palavras-chave: concorrência; controle de acesso; recuperação. Nota cheia (0,2): as três corretas. Metade (0,1): duas corretas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 3, 2, 'Explique o que poderia acontecer com o saldo se a funcionalidade da situação 1 não existisse.', 0.4, 'Sem controle de concorrência, as duas transferências poderiam **ler o mesmo saldo ao mesmo tempo** e uma **sobrescrever a outra**: o saldo final ficaria **errado** (por exemplo, sair dinheiro duas vezes mas descontar só uma, ou a conta ficar negativa sem permissão).', 'Palavras-chave: mesmo momento; uma sobrescreve a outra; saldo errado/inconsistente. Nota cheia (0,4): explica o conflito e o efeito no saldo. Metade (0,2): diz só "o saldo fica errado" sem explicar o conflito. Zero (0): resposta sem relação com acesso simultâneo.'),
      (v_atividade, 3, 3, 'Cite outra funcionalidade do SGBD que não aparece nas situações e dê um exemplo dela no app de banco.', 0.4, 'Exemplos: **armazenamento** (as transações continuam guardadas por anos); **integridade** (não aceitar transferência de valor negativo ou para conta inexistente); **consulta** (mostrar o extrato do mês).', 'Palavras-chave: funcionalidade diferente das três (armazenamento, integridade ou consulta) + exemplo no app. Nota cheia (0,4): funcionalidade correta com exemplo coerente. Metade (0,2): funcionalidade certa sem exemplo, ou exemplo certo com nome trocado. Zero (0): repete concorrência, acesso ou recuperação.'),
      (v_atividade, 4, 1, 'Diga qual problema da planilha explica o sumiço das vendas.', 0.2, '**Conflito de versões / falta de controle de concorrência**: quando dois vendedores salvam, a versão de um **sobrescreve** a do outro.', 'Palavras-chave: conflito de versões; concorrência; sobrescrever. Nota cheia (0,2): identifica o problema. Metade (0,1): "a planilha dá erro" sem dizer qual. Zero (0): culpa só o vendedor ou o computador.'),
      (v_atividade, 4, 2, 'Compare planilha e banco de dados em dois aspectos (por exemplo: volume de registros, regras, permissões) aplicados à loja.', 0.4, 'Dois aspectos, por exemplo: **volume** — com 8 mil pedidos a planilha fica lenta, o banco consulta rápido com índices; **regras** — a planilha aceita dados errados, o banco garante restrições; **permissões** — a planilha é tudo ou nada, o banco dá permissão por tabela e ação; **acesso simultâneo** — o banco controla a concorrência.', 'Palavras-chave: dois aspectos comparados (planilha × banco) aplicados à loja. Nota cheia (0,4): dois aspectos comparados corretamente. Metade (0,2): um aspecto comparado, ou dois citados sem comparar. Zero (0): comparação errada (ex.: "planilha é mais segura").'),
      (v_atividade, 4, 3, 'Diga em que situação uma planilha ainda é adequada e justifique.', 0.4, 'A planilha é adequada para **listas pequenas, usadas por uma pessoa ou poucas, sem integração com sistema** (ex.: controle pessoal de tarefas ou um levantamento rápido), porque não precisa de concorrência, regras nem permissões.', 'Palavras-chave: pouco volume; poucos usuários; sem integração; justificativa. Nota cheia (0,4): situação coerente + justificativa. Metade (0,2): situação coerente sem justificativa. Zero (0): diz que a planilha nunca serve ou que serve para o sistema da loja.'),
      (v_atividade, 5, 1, 'Diga o que é redundância de dados usando a tabela da loja como exemplo.', 0.2, '**Redundância** é o **mesmo dado copiado em vários lugares**: o nome, o telefone e o endereço da cliente estão **repetidos em cada pedido**.', 'Palavras-chave: mesmo dado repetido; exemplo da tabela. Nota cheia (0,2): definição + exemplo. Metade (0,1): só definição ou só exemplo. Zero (0): confunde com backup ou falta de dados.'),
      (v_atividade, 5, 2, 'Explique por que a correção de só um pedido gerou inconsistência e qual o prejuízo para a loja.', 0.4, 'Como o endereço está repetido, corrigir um só pedido deixou **versões diferentes do mesmo dado** (inconsistência). A loja pode **entregar no endereço antigo**, emitir nota errada e não saber qual endereço é o certo.', 'Palavras-chave: versões diferentes do mesmo dado; inconsistência; prejuízo concreto. Nota cheia (0,4): explica a causa e um prejuízo. Metade (0,2): só a causa ou só o prejuízo. Zero (0): explicação sem relação com a repetição.'),
      (v_atividade, 5, 3, 'Proponha como organizar os dados para que o endereço seja guardado uma única vez e justifique.', 0.4, 'Criar uma **tabela de clientes** com o endereço guardado **uma única vez** e, na tabela de pedidos, guardar só o **identificador do cliente** (id). Assim, ao mudar o endereço, a correção vale para todos os pedidos e não há inconsistência.', 'Palavras-chave: tabela de clientes separada; pedido guarda o id do cliente; atualização em um lugar só. Nota cheia (0,4): proposta + justificativa. Metade (0,2): proposta sem justificativa ou justificativa sem proposta clara. Zero (0): "corrigir todos os pedidos à mão" como solução.'),
      (v_atividade, 6, 1, 'Diga qual parte do sistema mostra a tela de login e envia o pedido.', 0.2, 'O **front-end** (a página no navegador).', 'Palavras-chave: front-end/navegador/tela. Nota cheia (0,2): front-end. Metade (0,1): "o site" sem distinguir. Zero (0): back-end ou banco.'),
      (v_atividade, 6, 2, 'Explique o que o back-end faz com o e-mail e a senha e como ele conversa com o banco.', 0.4, 'O **back-end** recebe e-mail e senha, aplica as **regras** (confere o usuário, compara a senha protegida) e **monta uma consulta SQL** que envia ao **SGBD** para buscar o usuário pelo e-mail.', 'Palavras-chave: back-end; regras; consulta SQL; envia ao SGBD. Nota cheia (0,4): regras + SQL ao SGBD. Metade (0,2): só "confere a senha" sem a conversa com o banco. Zero (0): diz que o front-end consulta o banco direto.'),
      (v_atividade, 6, 3, 'Explique o que o SGBD faz nesse login e o que ele devolve ao back-end.', 0.4, 'O **SGBD executa a consulta**, procura o usuário na tabela e **devolve a linha encontrada** (ou nenhuma) ao back-end, que decide se o login é válido.', 'Palavras-chave: executa a consulta; procura na tabela; devolve as linhas/resultado. Nota cheia (0,4): execução + retorno. Metade (0,2): só "guarda os usuários". Zero (0): diz que o SGBD mostra a página "Minha conta".'),
      (v_atividade, 7, 1, 'Diga se a decisão é adequada ou não, em uma frase.', 0.2, '**Não é adequada**: o banco não pode ficar acessível pelo navegador.', 'Palavras-chave: não adequada/errada. Nota cheia (0,2): não adequada. Metade (0,1): "depende" com alguma ressalva de segurança. Zero (0): adequada.'),
      (v_atividade, 7, 2, 'Explique o risco de deixar o banco acessível diretamente pelo navegador.', 0.4, 'Qualquer pessoa que abrir o código da página vê o **endereço e a senha** e pode **ler, alterar ou apagar** todos os dados (inclusive dados pessoais), sem passar pelas regras do sistema.', 'Palavras-chave: senha exposta; qualquer pessoa; ler/alterar/apagar dados; dados pessoais. Nota cheia (0,4): risco concreto explicado. Metade (0,2): "é inseguro" sem dizer o que pode acontecer. Zero (0): risco sem relação ("a página fica lenta").'),
      (v_atividade, 7, 3, 'Explique como a conexão com o banco deve ser feita e por quem.', 0.4, 'Quem se conecta ao banco é o **back-end**, no servidor, com **usuário e senha próprios da aplicação** (com o mínimo de permissões), guardados fora do código do navegador; o front-end só conversa com o back-end.', 'Palavras-chave: back-end; servidor; usuário/senha próprios; front-end não acessa o banco. Nota cheia (0,4): quem conecta + como. Metade (0,2): só "pelo back-end". Zero (0): mantém a conexão no navegador.'),
      (v_atividade, 8, 1, 'Separe os cinco gerenciadores em relacionais e não relacionais.', 0.2, '**Relacionais:** PostgreSQL, MySQL, SQLite. **Não relacionais:** MongoDB, Redis.', 'Nota cheia (0,2): os cinco corretos. Metade (0,1): um erro. Zero (0): dois ou mais erros.'),
      (v_atividade, 8, 2, 'Explique a diferença entre o modelo relacional e o não relacional na forma de organizar os dados.', 0.4, 'No **relacional**, os dados ficam em **tabelas** (linhas e colunas) ligadas por **chaves**, e usa-se **SQL**. No **não relacional**, os dados ficam em outras estruturas, como **documentos**, **chave-valor** ou **grafos**, com estrutura mais flexível.', 'Palavras-chave: tabelas/linhas/colunas/chaves/SQL × documentos/chave-valor/grafos. Nota cheia (0,4): descreve os dois modelos. Metade (0,2): descreve só um. Zero (0): descrição trocada.'),
      (v_atividade, 8, 3, 'Diga qual gerenciador é usado nesta UC e dois motivos para essa escolha.', 0.4, '**PostgreSQL**, porque é **gratuito e de código aberto**, **robusto** e usado em serviços como o **Supabase** (também: muito usado no mercado, segue bem o padrão SQL).', 'Palavras-chave: PostgreSQL + dois motivos. Nota cheia (0,4): PostgreSQL + dois motivos. Metade (0,2): PostgreSQL + um motivo. Zero (0): outro gerenciador.'),
      (v_atividade, 9, 1, 'Diga o que representam a tabela, uma coluna e uma linha nesse exemplo.', 0.2, 'A **tabela** "aluno" representa o assunto alunos; uma **coluna** (ex.: email) é uma característica do aluno; uma **linha** (ex.: "1, Ana Souza...") é um aluno.', 'Nota cheia (0,2): os três corretos. Metade (0,1): dois corretos. Zero (0): um ou nenhum.'),
      (v_atividade, 9, 2, 'Explique para que serve a coluna id e o que aconteceria se dois alunos tivessem o mesmo id.', 0.4, 'O **id identifica cada linha sem repetição**, para o sistema achar exatamente aquele aluno. Se dois alunos tivessem o mesmo id, o sistema **não saberia qual é qual**: poderia mostrar, alterar ou apagar o aluno errado.', 'Palavras-chave: identifica; sem repetição/único; aluno errado. Nota cheia (0,4): função + consequência. Metade (0,2): só a função. Zero (0): diz que o id guarda dados do aluno, como a idade.'),
      (v_atividade, 9, 3, 'Explique o que a consulta SELECT nome FROM aluno WHERE cidade = ''Blumenau'' devolve e o papel de cada parte (SELECT, FROM e WHERE).', 0.4, 'Devolve o **nome dos alunos de Blumenau** (no exemplo, **Bruno Lima**). **SELECT** escolhe as colunas mostradas (nome), **FROM** indica a tabela (aluno) e **WHERE** filtra as linhas (cidade = ''Blumenau'').', 'Palavras-chave: Bruno Lima/alunos de Blumenau; SELECT colunas; FROM tabela; WHERE filtro. Nota cheia (0,4): resultado + papel das três partes. Metade (0,2): resultado certo e uma ou duas partes explicadas. Zero (0): diz que a consulta apaga ou altera dados.'),
      (v_atividade, 10, 1, 'Diga por que a gestão do tempo é importante nesta UC.', 0.2, 'Porque o **projeto cresce aula a aula** e cada etapa depende da anterior; sem organizar o tempo, as entregas atrasam.', 'Palavras-chave: projeto contínuo; etapas dependentes; atraso. Nota cheia (0,2): justificativa com a dependência entre etapas. Metade (0,1): "para não atrasar" sem explicar. Zero (0): sem relação.'),
      (v_atividade, 10, 2, 'Explique o risco de deixar a modelagem para o fim, considerando a ordem das etapas da UC.', 0.4, 'A UC segue a ordem **entender o pedido → modelar → preparar o SGBD → construir com SQL**. Sem a modelagem, as tabelas ficam com **redundância e erros** e precisam ser **refeitas**, atrasando todas as aulas de construção (12 a 20).', 'Palavras-chave: ordem das etapas; tabelas sem modelo com erros/redundância; retrabalho. Nota cheia (0,4): ordem + consequência. Metade (0,2): só a consequência genérica. Zero (0): concorda com deixar a modelagem para o fim.'),
      (v_atividade, 10, 3, 'Monte para o colega um plano de estudos curto com três itens (o que entregar, tempo de revisão e quando pedir ajuda) e justifique um deles.', 0.4, 'Exemplo: (1) **entregar** a atividade de cada aula na mesma semana; (2) **reservar 1 hora por semana** para revisar SQL; (3) **pedir ajuda** ao professor ou colega quando travar mais de 20 minutos. Justificativa de um item (ex.: a revisão semanal evita acumular dúvidas para a avaliação).', 'Palavras-chave: três itens (entrega, revisão, ajuda) + justificativa de um. Nota cheia (0,4): três itens coerentes + justificativa. Metade (0,2): itens incompletos ou sem justificativa. Zero (0): plano sem relação com a UC.');
end $$;
